import { useEffect, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, RotateCcw, ZoomIn, ZoomOut } from 'lucide-react';
import type { PredictionCue } from '../assistant/predictionBrief';
import { COLORS } from '../lib/format';
import type { DemoData, Interval } from '../types';
import { createRobotScene, validateGeometry, type RobotGeometry } from './scene';
import { positionAtPlayhead, positionFixture, torqueAtPlayhead, validatePositions, type PositionData } from './telemetry';

type Props = { prediction?: PredictionCue; data: DemoData; playhead: number; interval: Interval; highlighted: string[]; onHighlight: (id: string) => void };
export default function RobotPanel({ prediction, data, playhead, interval, highlighted, onHighlight }: Props) {
  const host = useRef<HTMLDivElement>(null);
  const scene = useRef<ReturnType<typeof createRobotScene> | null>(null);
  const callback = useRef(onHighlight); callback.current = onHighlight;
  const highlights = useRef(highlighted); highlights.current = highlighted;
  const cursor = useRef(playhead); cursor.current = playhead;
  const geometry = useRef<RobotGeometry | null>(null);
  const [positions, setPositions] = useState<PositionData | null>(null);
  const [positionError, setPositionError] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    const controller = new AbortController(); let alive = true;
    setLoading(true); setError(''); setPositions(null); setPositionError('');
    const positionUrl = positionFixture(data.recording.id);
    const positionRequest = positionUrl
      ? fetch(positionUrl, { signal: controller.signal }).then(async response => {
        if (!response.ok) throw new Error('Measured joint positions could not be loaded.');
        const value: unknown = await response.json(); validatePositions(value, data.recording.id);
        if ((value.endSeconds ?? value.times[value.times.length - 1]) > data.recording.durationSeconds + 1e-8) throw new Error('Position timing does not match this recording.');
        return { value, message: '' };
      }).catch(() => ({ value: null, message: 'Positions unavailable · fixed illustrative pose' }))
      : Promise.resolve({ value: null, message: 'No validated positions for this recording · fixed illustrative pose' });
    const geometryRequest = fetch('/robot/kuka/kinematics.json', { signal: controller.signal }).then(async response => {
      if (!response.ok) throw new Error('Robot reference could not be loaded.');
      const model: unknown = await response.json(); validateGeometry(model); return model;
    });
    Promise.all([geometryRequest, positionRequest]).then(([model, measured]) => {
      if (!alive || !host.current) return;
      geometry.current = model;
      if (measured.value && measured.value.joints.some((joint, index) => joint.values.some(angle => angle < model.joints[index].limitsRadians[0] - 1e-5 || angle > model.joints[index].limitsRadians[1] + 1e-5))) {
        measured = { value: null, message: 'Position mapping failed validation · fixed illustrative pose' };
      }
      const initial = measured.value ? positionAtPlayhead(measured.value, data.recording.id, cursor.current) : null;
      scene.current = createRobotScene(host.current, model, id => callback.current(id), () => {
        setError('The 3D graphics context was lost. Retry to restore it.');
      }, initial?.radians ?? model.illustrativePoseRadians);
      scene.current.highlight(highlights.current);
      setPositions(measured.value); setPositionError(measured.message);
    }).catch(reason => {
      if (alive && !controller.signal.aborted) setError(reason instanceof Error && reason.message.startsWith('Robot') ? reason.message : '3D is unavailable in this browser. The measured signals remain available.');
    }).finally(() => { if (alive) setLoading(false); });
    return () => { alive = false; controller.abort(); scene.current?.dispose(); scene.current = null; geometry.current = null; };
  }, [attempt, data.recording.id, data.recording.durationSeconds]);
  const atOnset = Boolean(prediction && Math.abs(playhead - prediction.onsetSeconds) <= .125);
  useEffect(() => { scene.current?.highlight(highlighted, atOnset ? prediction?.channelId : undefined); }, [highlighted, atOnset, prediction?.channelId, loading]);
  useEffect(() => {
    const measured = positions ? positionAtPlayhead(positions, data.recording.id, playhead) : null;
    const angles = measured?.radians ?? geometry.current?.illustrativePoseRadians;
    if (angles) scene.current?.pose(angles);
  }, [positions, playhead, data.recording.id]);
  const sample = torqueAtPlayhead(data, playhead);
  const measured = positions ? positionAtPlayhead(positions, data.recording.id, playhead) : null;
  const poseStatus = measured ? `Recorded articulation · ${measured.time.toFixed(3)} s` : loading ? 'Loading joint positions…' : 'Fixed illustrative pose';
  const selectedMarker = data.events.find(event => event.timeSeconds >= interval.start && event.timeSeconds < interval.end);
  const rawAvailable = interval.start >= data.detail.startSeconds && interval.end <= data.detail.endSeconds;
  return <div className="robot-panel">
    <div className="robot-caption"><strong>KUKA LWR4+ <span>· schematic</span></strong><span>{poseStatus}</span></div>
    <div className={`robot-event-cue${atOnset ? ' at-onset' : ''}`} aria-label="Robot event context">
      {prediction ? <><strong>{atOnset ? 'At predicted onset' : playhead < prediction.onsetSeconds ? 'Before predicted onset' : 'After predicted onset'} · {prediction.onsetSeconds.toFixed(3)} s</strong><span>{prediction.title}{prediction.channelId ? ` · strongest response J${prediction.channelId.slice(-1)}` : ''}. Highlight is a time cue, not an impact location.</span></> : selectedMarker ? <><strong>Publisher marker · {selectedMarker.timeSeconds.toFixed(3)} s</strong><span>{rawAvailable ? 'Annotated event time. Analyze the interval for a model prediction.' : 'Annotated event time. Only overview measurements are available here.'}</span></> : <><strong>Recorded movement</strong><span>Select an event and analyze its torque to investigate contact.</span></>}
    </div>
    <div className="robot-content">
      <div className="robot-stage">
        <div className="robot-canvas" ref={host} role="img" aria-label={measured ? `Seven-joint schematic with recorded articulation at ${measured.time.toFixed(3)} seconds. Body shape and global base orientation are illustrative. Use joint buttons to highlight telemetry.` : 'Seven-joint robot schematic in a fixed illustrative pose. Measured articulation is unavailable at this time. Use joint buttons to highlight telemetry.'}/>
        {loading && <div className="robot-message" role="status">Loading robot reference…</div>}
        {error && <div className="robot-message" role="alert"><p>{error}</p><button className="btn" onClick={() => setAttempt(n => n + 1)}>Retry 3D</button></div>}
        {!loading && !error && <div className="robot-camera" role="group" aria-label="Robot camera controls">
          <button className="icon-button" aria-label="Rotate view left" onClick={() => scene.current?.rotate(-1)}><ArrowLeft size={13}/></button>
          <button className="icon-button" aria-label="Rotate view right" onClick={() => scene.current?.rotate(1)}><ArrowRight size={13}/></button>
          <button className="icon-button" aria-label="Zoom in on robot" onClick={() => scene.current?.zoom(.85)}><ZoomIn size={13}/></button>
          <button className="icon-button" aria-label="Zoom out from robot" onClick={() => scene.current?.zoom(1.18)}><ZoomOut size={13}/></button>
          <button className="icon-button" aria-label="Reset robot camera" onClick={() => scene.current?.reset()}><RotateCcw size={13}/></button>
        </div>}
      </div>
      <div className="robot-joints" aria-label="Measured joint torque at replay cursor">
        <div className="robot-joint-heading"><span>Joint</span><span>Nm</span></div>
        {data.channels.map((channel, i) => <button key={channel.id} aria-pressed={highlighted.includes(channel.id)}
          aria-label={`Highlight ${channel.name} in robot and signals`} onClick={() => onHighlight(channel.id)}>
          <span><i style={{ background: COLORS[i] }}/>J{i + 1}</span><span className="mono">{sample?.channels.find(c => c.id === channel.id)?.value.toFixed(3) ?? '—'}</span>
        </button>)}
        <p className="mono">{sample ? `${sample.time.toFixed(3)} s` : 'No sample'}</p>
      </div>
    </div>
    <footer className="robot-footer" title={positions?.validation.scope}><span>{measured ? positions?.validation.mappingVerified ? 'Recorded angles · schematic frame' : 'Recorded angles · reference mapping; schematic frame' : positionError || 'No position sample at this cursor · fixed pose'}</span><span>{sample?.resolution === 'raw' ? 'Torque · 1 kHz raw' : 'Torque · 100 Hz overview'}</span></footer>
  </div>;
}
import { useEffect, useState } from 'react';
import type { Services } from '../services';
import type { DemoData, Interval } from '../types';
import { modelWindowIssue } from './modelWindow';
import { withRawWindow } from './rawWindow';

export function useRawWindow(source: DemoData, datasetId: string, interval: Interval, services: Services) {
  const [attempt, setAttempt] = useState(0);
  const key = `${datasetId}:${source.recording.id}:${interval.start}:${interval.end}:${attempt}`;
  const sourceAlreadyCoversInterval = !modelWindowIssue(source, interval, interval.end);
  const eligible = services.connected && !sourceAlreadyCoversInterval && interval.start >= 0 && interval.end <= source.recording.durationSeconds && Math.abs(interval.end - interval.start - 1.024) < 1e-8;
  const [loaded, setLoaded] = useState<{key: string; data?: DemoData; error?: string}>();
  useEffect(() => {
    if (!eligible) return;
    let active = true;
    const snapshot = { ...interval };
    services.getWindow(source.recording.id, snapshot.start, snapshot.end, Array.from({length:7}, (_,i)=>`joint_${i+1}`), 1024)
      .then(response => { const data = withRawWindow(source, datasetId, snapshot, response); if (active) setLoaded({key, data}); })
      .catch(e => { if (active) setLoaded({key, error: e instanceof Error ? e.message : 'Raw telemetry could not load.'}); });
    return () => { active = false; };
  }, [source, datasetId, interval.start, interval.end, services, eligible, key]);
  const current = eligible && loaded?.key === key ? loaded : undefined;
  return { data: current?.data ?? source, loading: eligible && !current, error: current?.error, retry: () => setAttempt(n => n + 1) };
}
import { useMemo, useRef } from 'react';
import { Crosshair, Maximize2 } from 'lucide-react';
import { downsample, selectWindow } from '../lib/data';
import { COLORS } from '../lib/format';
import type { PredictionCue } from '../assistant/predictionBrief';
import type { DemoData, Interval } from '../types';

type Props = { visibleChannelIds?: string[]; prediction?: PredictionCue; data: DemoData; playhead: number; interval: Interval; viewport: Interval; highlighted: string[]; following: boolean; zoom: number; onSelect: (v: Interval) => void; onFollow: () => void; onZoom: (seconds: number) => void };

export default function SignalViewer({ visibleChannelIds, prediction, data, playhead, interval, viewport, highlighted, following, zoom, onSelect, onFollow, onZoom }: Props) {
  const hover = useRef<number | null>(null);
  const panel = useRef<HTMLDivElement>(null);
  const drag = useRef<number | null>(null);
  const end = Math.min(viewport.end, playhead);
  const visible = useMemo(() => {
    if (end <= viewport.start) return null;
    try { return selectWindow(data, { start: viewport.start, end }); } catch { return null; }
  }, [data, viewport.start, end]);
  const plots = useMemo(() => data.channels.map((channel, index) => {
    const values = visible?.channels[index].values ?? [];
    const times = visible?.times ?? [];
    const points = downsample(times.map((x, i) => ({ x, y: values[i] })), 600);
    let low = values.length ? Math.min(...values) : -1;
    let high = values.length ? Math.max(...values) : 1;
    const pad = Math.max((high - low) * .15, .01); low -= pad; high += pad;
    const x = (t: number) => (t - viewport.start) / (viewport.end - viewport.start) * 1000;
    const y = (v: number) => 70 - (v - low) / (high - low) * 64;
    const path = points.map((p, i) => `${i ? 'L' : 'M'}${x(p.x).toFixed(2)},${y(p.y).toFixed(2)}`).join(' ');
    return { channel, colorIndex: index, values, times, path, low, high, zero: y(0), last: values.at(-1) };
  }).filter(p => !visibleChannelIds || visibleChannelIds.includes(p.channel.id)), [data, visible, viewport, visibleChannelIds]);
  function pointerTime(event: React.PointerEvent<SVGSVGElement>) {
    const rect = event.currentTarget.getBoundingClientRect();
    return Math.max(viewport.start, Math.min(playhead, viewport.start + (event.clientX - rect.left) / rect.width * (viewport.end - viewport.start)));
  }
  function beginSelection(event: React.PointerEvent<SVGSVGElement>) {
    if (!event.isPrimary || event.button !== 0) return;
    drag.current = pointerTime(event);
    event.currentTarget.setPointerCapture(event.pointerId);
  }
  function finishSelection(event: React.PointerEvent<SVGSVGElement>) {
    if (drag.current === null) return;
    const time = pointerTime(event);
    const start = Math.min(time, drag.current), finish = Math.max(time, drag.current);
    drag.current = null;
    if (finish - start >= .01) onSelect({ start, end: finish });
  }
  function cancelSelection() { drag.current = null; }
  function showCursor(time: number | null) {
    hover.current = time;
    if (!panel.current) return;
    panel.current.style.setProperty('--cursor', `${time === null ? -100 : (time - viewport.start) / (viewport.end - viewport.start) * 100}%`);
    panel.current.querySelectorAll<HTMLElement>('[data-sample-value]').forEach((el, i) => {
      const p = plots[i];
      let value = p.last;
      if (time !== null && p.times.length) {
        let lo = 0, hi = p.times.length - 1;
        while (lo < hi) { const mid = (lo + hi) >>> 1; if (p.times[mid] < time) lo = mid + 1; else hi = mid; }
        const idx = lo > 0 && Math.abs(p.times[lo - 1] - time) < Math.abs(p.times[lo] - time) ? lo - 1 : lo;
        value = p.values[idx];
      }
      el.textContent = value === undefined ? '—' : value.toFixed(3);
    });
    const label = panel.current.querySelector('[data-cursor-time]');
    if (label) label.textContent = time === null ? 'Hover to inspect · drag to select' : `Cursor ${time.toFixed(3)} s · nearest available samples`;
  }
  const left = Math.max(0, (interval.start - viewport.start) / (viewport.end - viewport.start) * 100);
  const right = Math.min(100, (Math.min(interval.end, playhead) - viewport.start) / (viewport.end - viewport.start) * 100);
  const predictedOnset = prediction?.onsetSeconds;
  const predictedOnsetPercent = predictedOnset !== undefined && predictedOnset >= viewport.start && predictedOnset <= end
    ? (predictedOnset - viewport.start) / (viewport.end - viewport.start) * 100
    : undefined;
  const onsetNearRightEdge = predictedOnsetPercent !== undefined && predictedOnsetPercent > 82;
  return <section className="signals-panel" ref={panel} aria-label="Synchronized torque signals">
    <header className="panel-heading"><div><h2>{visibleChannelIds ? "Torque evidence" : "All joint signals"}</h2><span>Signed external torque</span></div><div className="plot-actions"><select aria-label="Signal zoom" value={following ? String(zoom) : "selection"} onChange={e => onZoom(Number(e.target.value))}><option value="selection" disabled>Selection</option><option value="1.024">1.024 s</option><option value="5">5 s</option><option value="10">10 s</option><option value="0">Full history</option></select><button className="icon-button" title="Follow playhead" aria-label="Follow playhead" aria-pressed={following} onClick={onFollow}><Crosshair size={16}/></button></div></header>
    <div className="signal-strips">{plots.map((p, plotIndex) => <div key={p.channel.id} className={`signal-strip ${highlighted.includes(p.channel.id) ? 'signal-highlighted' : ''}`} data-channel={p.channel.id}>
      <div className="strip-heading"><span className="channel-name"><i style={{ background: COLORS[p.colorIndex] }}/>{p.channel.name}<span className="unit">Nm</span></span><span className="mono sample-value" data-sample-value>{p.last?.toFixed(3) ?? '—'}</span></div>
      <div className="plot-frame"><div className="y-labels"><span>{p.high.toFixed(p.high-p.low < 1 ? 2 : 1)}</span><span>{p.low.toFixed(p.high-p.low < 1 ? 2 : 1)}</span></div><div className="plot-area">
        {right > left && <div className="selection-band" style={{ left: `${left}%`, width: `${right - left}%` }}/>}<div className="hover-guide"/>
        {predictedOnsetPercent !== undefined && <div className={`model-onset-cue${onsetNearRightEdge ? ' at-right-edge' : ''}`} style={{ left: `${predictedOnsetPercent}%` }}>{plotIndex === 0 && <span>Predicted onset</span>}</div>}
        <svg viewBox="0 0 1000 76" preserveAspectRatio="none" role="img" aria-label={`${p.channel.name}, signed external torque in Nm, ${viewport.start.toFixed(3)} to ${end.toFixed(3)} seconds`} onPointerMove={e => showCursor(pointerTime(e))} onPointerLeave={() => showCursor(null)} onPointerDown={beginSelection} onPointerUp={finishSelection} onPointerCancel={cancelSelection} onLostPointerCapture={cancelSelection}>
          {[0, 250, 500, 750, 1000].map(x => <line key={x} x1={x} x2={x} y1="0" y2="76" className="chart-grid"/>)}
          {[18, 38, 58].map(y => <line key={y} x1="0" x2="1000" y1={y} y2={y} className="chart-grid"/>)}
          {p.zero > 0 && p.zero < 76 && <line x1="0" x2="1000" y1={p.zero} y2={p.zero} className="chart-zero"/>}
          {data.events.filter(e => e.timeSeconds >= viewport.start && e.timeSeconds <= end).map(e => <line key={e.id} x1={(e.timeSeconds - viewport.start)/(viewport.end-viewport.start)*1000} x2={(e.timeSeconds - viewport.start)/(viewport.end-viewport.start)*1000} y1="0" y2="76" className="event-line"/>)}
          <path d={p.path} fill="none" stroke={COLORS[p.colorIndex]} strokeWidth="1.3" vectorEffect="non-scaling-stroke"/>
        </svg>
      </div></div>
    </div>)}</div>
    <div className="shared-axis">{[0, .25, .5, .75, 1].map(v => <span key={v}>{(viewport.start+(viewport.end-viewport.start)*v).toFixed(2)} s</span>)}</div>
    <footer className="plot-footer"><span data-cursor-time>Hover to inspect · drag to select</span><span><Maximize2 size={12}/>{visible ? `${visible.sampleRateHz >= 1000 ? `${(visible.sampleRateHz / 1000).toFixed(0)} kHz` : `${visible.sampleRateHz.toFixed(0)} Hz`} ${visible.resolution === 'raw' ? 'raw' : 'overview'} · extrema-preserving plot` : 'No replayed samples'}</span></footer>
  </section>;
}

