 13	  useEffect(() => {
 14	    if (!eligible) return;
 15	    let active = true;
 16	    const snapshot = { ...interval };
 17	    services.getWindow(source.recording.id, snapshot.start, snapshot.end, Array.from({length:7}, (_,i)=>`joint_${i+1}`), 1024)
 18	      .then(response => { const data = withRawWindow(source, datasetId, snapshot, response); if (active) setLoaded({key, data}); })
