 20	    return () => { active = false; };
 21	  }, [source, datasetId, interval.start, interval.end, services, eligible, key]);
 22	  const current = eligible && loaded?.key === key ? loaded : undefined;
 23	  return { data: current?.data ?? source, loading: eligible && !current, error: current?.error, retry: () => setAttempt(n => n + 1) };
