  4	import { modelWindowIssue } from './modelWindow';
  5	import { withRawWindow } from './rawWindow';
  6	
  7	export function useRawWindow(source: DemoData, datasetId: string, interval: Interval, services: Services) {
  8	  const [attempt, setAttempt] = useState(0);
  9	  const key = `${datasetId}:${source.recording.id}:${interval.start}:${interval.end}:${attempt}`;
 10	  const sourceAlreadyCoversInterval = !modelWindowIssue(source, interval, interval.end);
 11	  const eligible = services.connected && !sourceAlreadyCoversInterval && interval.start >= 0 && interval.end <= source.recording.durationSeconds && Math.abs(interval.end - interval.start - 1.024) < 1e-8;
 12	  const [loaded, setLoaded] = useState<{key: string; data?: DemoData; error?: string}>();
 13	  useEffect(() => {
 14	    if (!eligible) return;
 15	    let active = true;
 16	    const snapshot = { ...interval };
 17	    services.getWindow(source.recording.id, snapshot.start, snapshot.end, Array.from({length:7}, (_,i)=>`joint_${i+1}`), 1024)
 18	      .then(response => { const data = withRawWindow(source, datasetId, snapshot, response); if (active) setLoaded({key, data}); })
 19	      .catch(e => { if (active) setLoaded({key, error: e instanceof Error ? e.message : 'Raw telemetry could not load.'}); });
 20	    return () => { active = false; };
 21	  }, [source, datasetId, interval.start, interval.end, services, eligible, key]);
 22	  const current = eligible && loaded?.key === key ? loaded : undefined;
 23	  return { data: current?.data ?? source, loading: eligible && !current, error: current?.error, retry: () => setAttempt(n => n + 1) };
 24	}

