import copy
import hashlib
import http.client
import json
from pathlib import Path
import tempfile
import threading
import time
import unittest

from inference.server import DATASET_ID, MAX_BODY, envelope_indices, make_server
from inference.raw_recordings import CHANNEL_IDS, RawRecordingCatalog


class FakeRuntime:
    ready = True
    error = ""
    model_id = "test/checkpoint"
    revision = "test-revision"

    def __init__(self):
        self.entered = threading.Event()
        self.release = threading.Event()
        self.release.set()
        self.failure = False
        self.received = None

    def load(self):
        self.ready = True

    def generate(self, request, series, cancelled):
        self.received = (request, series)
        self.entered.set()
        self.release.wait(3)
        if self.failure:
            raise RuntimeError("private runtime detail")
        self.last_trace = {
            "model": self.model_id,
            "revision": self.revision,
            "window": request["window"],
            "samplesPerChannel": len(series[0]["values"]),
            "inputSha256": hashlib.sha256(
                json.dumps(series, sort_keys=True, allow_nan=False).encode()
            ).hexdigest(),
        }
        return 'Answer: {"contact":true}\nEvidence: generated test evidence.'


class FakeCnnRuntime:
    enabled = True
