class FakeRuntime:
    ready = True
    error = ""
    model_id = "test/checkpoint"
    revision = "test-revision"

    def __init__(self):
        self.entered = threading.Event()
        self.release = threading.Event()
        self.release.set()
        self.failure = False
        self.received = None
        self.calls = 0

    def load(self):
        self.ready = True

    def generate(self, request, series, cancelled):
        self.calls += 1
        self.received = (request, series)
        self.entered.set()
        self.release.wait(3)
        if self.failure:
            raise RuntimeError("private runtime detail")
        self.last_trace = {
            "model": self.model_id,
            "revision": self.revision,
            "window": request["window"],
            "samplesPerChannel": len(series[0]["values"]),
            "inputSha256": hashlib.sha256(
                json.dumps(series, sort_keys=True, allow_nan=False).encode()
            ).hexdigest(),
        }
        return 'Answer: {"contact":true}\nEvidence: generated test evidence.'


class FakeCnnRuntime:
    enabled = True
    ready = True
    error = ""
    model_id = "cnn-1d"
    revision = "cnn-test-revision"

    def validate_series(self, series):
        if len(series) != 7:
            raise ValueError("CNN requires all seven canonical joint channels")

    def predict(self, series, cancelled):
        return {
            "labels": [
                {"label": "event type: accidental", "score": 0.9},
                {"label": "contact: detected", "score": 0.9},
                {"label": "predicted onset: 12 ms"},
            ],
            "event_type": "accidental",
            "onset_sample": 12,
        }


